python3 -c "
import json
with open('/app/resources/treasury_bulletin_1972_04.json') as f:
    data = json.load(f)

# Print structure
def print_structure(obj, indent=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 3:
                print_structure(v, indent + 2)
    elif isinstance(obj, list) and len(obj) > 0 and indent < 3:
        print(' ' * indent + '[list with ' + str(len(obj)) + ' items]')
        if indent < 2:
            print_structure(obj[0], indent + 2)

print_structure(data)
" 2>&1 | head -100
